          const col=localStorage.getItem('selected_college'); if(!col ||!isVerified){ setScreen('college'); return; }
          let av:any=AVATARS[0]; try{ const s=localStorage.getItem('selected_avatar_data'); if(s) av=JSON.parse(s); }catch{}
          const safeAv={emoji:String(av?.emoji||"👻"), bg:String(av?.bg||"bg-zinc-900"), glow:String(av?.glow||""), level:String(av?.level||"Ghost")};
          await addDoc(collection(db,'users'),{ uid:u.uid, email:u.email||'', username:'Yak_'+Math.floor(Math.random()*9000+1000), avatar:safeAv.emoji, avatarBg:safeAv.bg, avatarGlow:safeAv.glow, avatarLevel:safeAv.level, college:String(col), collegeEmail:String(localStorage.getItem('college_email')||''), rollNumber:String(localStorage.getItem('roll_number')||''), idImage:String(localStorage.getItem('id_image')||''), idName:String(localStorage.getItem('id_name')||''), verifyMethod:String(localStorage.getItem('verify_method')||'email'), idVerified: localStorage.getItem('verify_method')==='id'? false : true, yakarma:150, totalPosts:0, streak:1, likedPosts:[], dislikedPosts:[], reportedPosts:[], createdAt:serverTimestamp() });
