          <div className="grid grid-cols-1 gap-3 mt-3">{COLLEGES.map(c=>{const a=selectedCollege===c.id; const count=collegeCounts[c.id]||0; return <button key={c.id} onClick={()=>setSelectedCollege(c.id)} className={`p-4 rounded-[22px] border-2 text-left flex items-center justify-between ${a?'bg-white text-black border-white scale-[1.03] shadow-[0_0_30px_rgba(255,255,255,0.25)]':'bg-[#0a0a0f] border-zinc-900 text-white hover:border-zinc-800'}`}><div className="flex items-center gap-3"><div className={`w-12 h-12 rounded-[14px] bg-gradient-to-br ${c.color} flex items-center justify-center text-xl shadow-lg`}>{c.emoji}</div><div><p className="font-black text-[14px]">{c.label} • {c.city}</p><p className={`text-[11px] ${a?'text-black/60':'text-zinc-500'}`}>{count} real attractive • {c.domains[0]}</p></div></div><div className={`w-7 h-7 rounded-full border-2 flex items-center justify-center font-black text-xs ${a?'bg-black text-white border-black':'border-zinc-700 text-zinc-600'}`}>{a?'✓':count>0?String(count):'+'}</div></button>})}</div>
