          <div className="flex items-center gap-3"><div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center font-black text-black attractive-glow">Y</div><div><p className="font-black text-[15px] tracking-tighter leading-none">{userData.college} Ultra ✨ • {collegeCounts[userData.college]||0} real</p><p className="text-[11px] text-zinc-500 font-bold">🔥 Streak {streak} days • {yaks.length} attractive yaks</p></div></div>
