            <div className="bg-gradient-to-br from-violet-600 via-indigo-600 to-purple-700 rounded-[24px] p-5 shimmer border border-violet-400/30"><p className="text-[11px] font-black tracking-[0.2em] text-white/70">🏆 {userData.college} ULTRA LEADERBOARD ✨</p><p className="text-[22px] font-black mt-1 text-white">Attractive Kings 👑🔥</p><p className="text-[12px] text-white/70 mt-1">Most attractive + streak + karma</p></div>
            {leaderboard.map((u:any,i:number)=><div key={u.id} className={`bg-[#0a0a0f] border rounded-[20px] p-4 flex items-center justify-between ${i===0?'border-yellow-500/50 shadow-[0_0_30px_rgba(234,179,8,0.25)] attractive-glow':i===1?'border-zinc-400/40':i===2?'border-orange-500/40 fire-glow':'border-zinc-900'} `}><div className="flex items-center gap-3"><div className={`w-10 h-10 rounded-full flex items-center justify-center font-black text-sm ${i===0?'bg-gradient-to-br from-yellow-400 to-orange-500 text-black attractive-glow':i===1?'bg-zinc-300 text-black':i===2?'bg-orange-500 text-black':'bg-zinc-900 text-zinc-500'}`}>{i+1}</div><div className={`w-11 h-11 rounded-full ${u.avatarBg||'bg-zinc-900'} flex items-center justify-center text-lg border-2 ${i===0?'border-yellow-500/50 attractive-glow':'border-zinc-800'}`}>{u.avatar||'👻'}</div><div><p className="font-black text-[14px] flex items-center gap-1">{u.username} {i===0&&'👑✨'} {u.id===userData.id&&'• YOU ✨'}</p><p className="text-[11px] text-zinc-500">{u.college} • {u.totalPosts||0} yaks • 🔥 {u.streak||1} streak</p></div></div><div className="text-right"><p className="text-[18px] font-black">{u.yakarma}</p><p className="text-[9px] font-bold tracking-widest text-zinc-500">KARMA ✨</p></div></div>)}
